import{_ as o,a0 as p,w as l,s as r,ao as d,I as i,x as s,a1 as a,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"我是如何使用 Linux fmt 命令来格式化文本 | LCTT x X-CMD","titleTemplate":false,"description":"我是如何使用 Linux fmt 命令来格式化文本 | LCTT (202208) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"我是如何使用 Linux fmt 命令来格式化文本 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"我是如何使用 Linux fmt 命令来格式化文本 | LCTT (202208) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202208/20220721 How I use the Linux fmt command to format text","title":"我是如何使用 Linux fmt 命令来格式化文本","tag":"202208","desc":""},"relativePath":"202208/20220721 How I use the Linux fmt command to format text.md","filePath":"[post].md"}'),h={name:"202208/20220721 How I use the Linux fmt command to format text.md"};function c(f,e,m,g,u,k){const t=p("Link");return l(),r("div",null,[e[15]||(e[15]=d(`<h1 id="我是如何使用-linux-fmt-命令来格式化文本" tabindex="-1">我是如何使用 Linux fmt 命令来格式化文本 <a class="header-anchor" href="#我是如何使用-linux-fmt-命令来格式化文本" aria-label="Permalink to “我是如何使用 Linux fmt 命令来格式化文本”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202208/01/184300zbyfjayeyqa5pmcb.jpg" alt=""></p><blockquote><p>fmt 命令是一个简单的文本格式化程序。我将在这里展示如何使用它来格式化文本和邮件回复。</p></blockquote><p>当我为项目编写文档时，我经常以纯文本的形式编写自述文件和安装说明。我不需要使用 HTML 或者 Markdown 之类的标记语言来描述项目的功能或如何编译它。但是维护这样的文档可能会很痛苦。如果我需要更新我的 <code>Readme</code> 文件中的一个句子的中间位置，我需要重新格式化文本，以避免在我的其它文本中间出现一个很长或很短的行，而其它的行的格式是整整齐齐的 75 列。一些编辑器包含可以自动重新格式化文本以填充段落的功能，但并非所有的编辑器都这样做。这就是 Linux <code>fmt</code> 命令的用武之地。</p><h3 id="使用-linux-fmt-命令格式化文本" tabindex="-1">使用 Linux fmt 命令格式化文本 <a class="header-anchor" href="#使用-linux-fmt-命令格式化文本" aria-label="Permalink to “使用 Linux fmt 命令格式化文本”">​</a></h3><p><code>fmt</code> 命令是一个简单的文本格式化程序；它收集单词并填充段落，但不应用任何其它文本样式，例如斜体或粗体。这一切都是纯文本。使用 <code>fmt</code> 命令，你可以快速调整文本，使其更易于阅读。让我们从这个熟悉的示例文本开始:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat trek.txt </span></span>
<span class="line"><span>Space: the final</span></span>
<span class="line"><span>frontier. These are the voyages</span></span>
<span class="line"><span>of the starship Enterprise. Its</span></span>
<span class="line"><span>continuing mission: to explore</span></span>
<span class="line"><span>strange new worlds. To</span></span>
<span class="line"><span>seek out new life and new</span></span>
<span class="line"><span>civilizations. To boldly go</span></span>
<span class="line"><span>where no one has gone before!</span></span></code></pre></div><p>在这个实例文件中，每行都有不同的长度，并且它们以一种奇怪的方式换行。如果你对纯文本文件进行大量更改，你可以会遇到类似的奇怪的换行。要重新格式化此文本，你可以使用 <code>fmt</code> 命令将段落的行填充为统一长度：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fmt trek.txt </span></span>
<span class="line"><span>Space: the final frontier. These are the voyages of the starship</span></span>
<span class="line"><span>Enterprise. Its continuing mission: to explore strange new worlds. To</span></span>
<span class="line"><span>seek out new life and new civilizations. To boldly go where no one has</span></span>
<span class="line"><span>gone before!</span></span></code></pre></div><p>默认情况下，<code>fmt</code> 会将文本格式化为 75 的列宽大小，但你可以使用 <code>-w</code> 或 <code>--width</code> 选项进行更改：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fmt -w 60 trek.txt </span></span>
<span class="line"><span>Space: the final frontier. These are the voyages of</span></span>
<span class="line"><span>the starship Enterprise. Its continuing mission: to</span></span>
<span class="line"><span>explore strange new worlds. To seek out new life and new</span></span>
<span class="line"><span>civilizations. To boldly go where no one has gone before!</span></span></code></pre></div><h3 id="使用-linux-fmt-命令格式化电子邮件回复" tabindex="-1">使用 Linux fmt 命令格式化电子邮件回复 <a class="header-anchor" href="#使用-linux-fmt-命令格式化电子邮件回复" aria-label="Permalink to “使用 Linux fmt 命令格式化电子邮件回复”">​</a></h3><p>我加入了一个邮件列表，这里更喜欢纯文本电子邮件，这使得在列表服务器上归档电子邮件变得更加容易。但现实是并非每个人都以纯文本形式发送电子邮件。有时候，当我以纯文本形式回复这些电子邮件时，我的电子邮件客户端会将整个段落放在一行中。这使得在电子邮件中“引用”回复变得困难。</p><p>这是一个简单的例子。当我以纯文本形式回复电子邮件时，我的电子邮件客户端通过在每行前添加 <code>&gt;</code> 字符来“引用”对方的电子邮件。对于一条短消息，可能如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; I like the idea of the interim development builds.</span></span></code></pre></div><p>没有正确“换行”的长行将无法在我的纯文本电子邮件回复中正确显示，因为它只是前面带有 <code>&gt;</code> 字符的长行，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; I like the idea of the interim development builds. This should be a great way to test new changes that everyone can experiment with.</span></span></code></pre></div><p>为了解决这个问题，我打开了一个终端并将引用的文本复制并粘贴到一个新文件中。然后我使用 <code>-p</code> 或 <code>--prefix</code> 选项来告诉 <code>fmt</code> 在每一行之前使用什么字符作为“前缀”。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat &gt; email.txt</span></span>
<span class="line"><span>&gt; I like the idea of the interim development builds. This should be a great way to test new changes that everyone can experiment with.</span></span>
<span class="line"><span>^D</span></span>
<span class="line"><span>$ fmt -p &#39;&gt;&#39; email.txt</span></span>
<span class="line"><span>&gt; I like the idea of the interim development builds. This should be a</span></span>
<span class="line"><span>&gt; great way to test new changes that everyone can experiment with.</span></span></code></pre></div><p><code>fmt</code> 命令是一个非常简单的文本格式化程序，但它可以做很多有用的事情，可以帮助以纯文本形式编写和更新文档。要了解其它选项，例如 <code>-c</code> 或 <code>--crown-margin</code> 以匹配段落前两行缩进，例如项目列表。还可以尝试使用 <code>-t</code> 或者 <code>--tagged-paragraph</code> 来保留段落中第一行的缩进，就像缩进的段落一样。<code>-u</code> 或 <code>--uniform-spacing</code> 选项在单词之间使用一个空格，在句子之间使用两个空格。</p><hr>`,21)),i("p",null,[e[1]||(e[1]=s("via: ",-1)),a(t,{href:"https://opensource.com/article/22/7/fmt-trivial-text-formatter"},{default:n(()=>[...e[0]||(e[0]=[s("https://opensource.com/article/22/7/fmt-trivial-text-formatter",-1)])]),_:1})]),i("p",null,[e[6]||(e[6]=s("作者：",-1)),a(t,{href:"https://opensource.com/users/jim-hall"},{default:n(()=>[...e[2]||(e[2]=[s("Jim Hall",-1)])]),_:1}),e[7]||(e[7]=s(" 选题：",-1)),a(t,{href:"https://github.com/lkxed"},{default:n(()=>[...e[3]||(e[3]=[s("lkxed",-1)])]),_:1}),e[8]||(e[8]=s(" 译者：",-1)),a(t,{href:"https://github.com/perfiffer"},{default:n(()=>[...e[4]||(e[4]=[s("perfiffer",-1)])]),_:1}),e[9]||(e[9]=s(" 校对：",-1)),a(t,{href:"https://github.com/wxy"},{default:n(()=>[...e[5]||(e[5]=[s("wxy",-1)])]),_:1})]),i("p",null,[e[12]||(e[12]=s("本文由 ",-1)),a(t,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[10]||(e[10]=[s("LCTT",-1)])]),_:1}),e[13]||(e[13]=s(" 原创编译，",-1)),a(t,{href:"https://linux.cn/"},{default:n(()=>[...e[11]||(e[11]=[s("Linux中国",-1)])]),_:1}),e[14]||(e[14]=s(" 荣誉推出",-1))])])}const T=o(h,[["render",c]]);export{w as __pageData,T as default};
